<template>
  <!-- #ifdef H5 -->
  <view class="auth-page">
    <view class="auth-shell" :class="{ 'is-register': authMode === 'register' }">
      <view class="auth-form-side">
        <navigator class="auth-back" url="/pages/index/index">← 返回官网</navigator>
        <view class="auth-content">
          <view class="auth-mark"><image :src="brandMark" mode="aspectFit" /><text>SRAVX</text></view>
          <text class="auth-title">{{ authMode === 'login' ? '登录账号' : '创建账号' }}</text>
          <text class="auth-subtitle">{{ authMode === 'login' ? '登录后继续探索专业工具体验。' : '填写账号信息，开启 SRAVX 服务体验。' }}</text>
          <view class="auth-fields"><label><text>账号</text><input v-model.trim="h5Form.account" placeholder="手机号码或邮箱" placeholder-class="auth-placeholder" /></label><label class="auth-password"><text>密码</text><view><input v-model="h5Form.password" password placeholder="请输入密码" placeholder-class="auth-placeholder" /><text v-if="authMode === 'login'" class="auth-forgot">忘记密码？</text></view></label><label v-if="authMode === 'register'"><text>确认密码</text><input v-model="h5Form.confirmPassword" password placeholder="请再次输入密码" placeholder-class="auth-placeholder" /></label></view>
          <view class="auth-options"><label><checkbox :checked="h5Form.agreed" color="#0a6edb" @click="h5Form.agreed = !h5Form.agreed" /><text>{{ authMode === 'login' ? '记住我' : '同意服务协议与隐私政策' }}</text></label></view>
          <button class="auth-submit" @click="submitH5">{{ authMode === 'login' ? '登录' : '注册' }}</button>
          <view v-if="authMode === 'login'" class="auth-other"><text>其他方式登录</text><view class="auth-methods"><button class="auth-method active">账号</button><button class="auth-method">手机</button><button class="auth-method">邮箱</button></view></view>
          <text class="auth-note">H5 账号服务正在接入，当前可体验表单交互。</text>
        </view>
      </view>
      <view class="auth-switch-side">
        <view class="corner-disc corner-disc-top"></view><view class="corner-disc corner-disc-bottom"></view>
        <view class="switch-content"><text>{{ authMode === 'login' ? 'Hi, SRAVX Owner.' : 'Welcome Back!' }}</text><text>{{ authMode === 'login' ? '还没有账号？创建账号以同步你的专业服务记录。' : '已有账号？登录后继续你的 SRAVX 专业体验。' }}</text><button @click="switchAuth(authMode === 'login' ? 'register' : 'login')">{{ authMode === 'login' ? '创建账号' : '去登录' }}</button></view>
      </view>
    </view>
  </view>
  <!-- #endif -->
  <!-- #ifndef H5 -->
  <view class="page"><view class="header"><text class="ui-strong">加入 Sravx</text><text>完善您的信息以获得个性化体验</text></view><view class="form"><view class="field"><text>用户名</text><input v-model="form.username" maxlength="20" placeholder="支持中英文" /></view><view class="field"><text>性别</text><view class="genders"><view v-for="item in genders" :key="item" :class="{ active: form.gender === item }" @tap="form.gender = item">{{ item }}</view></view></view><view class="field"><text>生日</text><picker mode="date" start="1940-01-01" end="2015-12-31" :value="form.birthday" @change="form.birthday = $event.detail.value"><view :class="form.birthday ? 'value' : 'placeholder'">{{ form.birthday || '请选择出生日期' }}</view></picker></view><view class="field"><text>职业</text><picker :range="occupations" :value="occupationIndex" @change="occupationIndex = Number($event.detail.value); form.occupation = occupations[occupationIndex]"><view :class="form.occupation ? 'value' : 'placeholder'">{{ form.occupation || '请选择您的职业' }}</view></picker></view></view><view class="bottom"><button v-if="!hasPhone" :class="{ disabled: !ready }" open-type="getPhoneNumber" @getphonenumber="getPhone">开始使用</button><button v-else :class="{ disabled: !ready || saving }" @tap="submit">{{ saving ? '保存中...' : '开始使用' }}</button></view></view>
  <!-- #endif -->
</template>

<script>
import api from '../../common/api.js'
import auth from '../../common/auth.js'
import brandMark from '../../static/navigation/sravx-mark.png'
export default { data() { return { brandMark, authMode: 'login', h5Form: { account: '', password: '', confirmPassword: '', agreed: true }, form: { username: '', gender: '', birthday: '', occupation: '' }, genders: ['男', '女'], occupations: ['宠物美容师A级', '宠物美容师B级', '宠物美容师C级', '宠物美容学徒', '其他'], occupationIndex: -1, hasPhone: false, saving: false } }, computed: { ready() { const f = this.form; return !!(f.username.trim() && f.gender && f.birthday && f.occupation) } }, onLoad(options) { this.authMode = options && options.mode === 'register' ? 'register' : 'login'; this.hasPhone = !!(auth.user() && auth.user().phone) }, onShow() { this.hasPhone = !!(auth.user() && auth.user().phone) }, methods: { switchAuth(mode) { this.authMode = mode; this.h5Form.password = ''; this.h5Form.confirmPassword = '' }, submitH5() { const form = this.h5Form; if (!form.account || !form.password || (this.authMode === 'register' && !form.confirmPassword)) return uni.showToast({ title: '请完整填写账号信息', icon: 'none' }); if (this.authMode === 'register' && form.password !== form.confirmPassword) return uni.showToast({ title: '两次输入的密码不一致', icon: 'none' }); if (!form.agreed) return uni.showToast({ title: '请先阅读并同意服务协议', icon: 'none' }); uni.showToast({ title: 'H5 账号服务正在接入', icon: 'none' }) }, profile() { return { username: this.form.username.trim(), gender: this.form.gender, birthday: this.form.birthday, occupation: this.form.occupation } }, async getPhone(event) { if (!this.ready) return; if (!event.detail || event.detail.errMsg !== 'getPhoneNumber:ok') return uni.showToast({ title: '请授权手机号后继续使用', icon: 'none' }); const detail = event.detail; if (!detail.code && !detail.cloudID && !(detail.encryptedData && detail.iv)) return uni.showToast({ title: '未获取到手机号授权凭证，请重试', icon: 'none' }); this.saving = true; try { const login = await api.login({ code: detail.code, cloudID: detail.cloudID, encryptedData: detail.encryptedData, iv: detail.iv, profile: this.profile() }); if (!login || !login.phone) throw new Error('手机号绑定失败，请重新授权'); if (!login.profileSaved) await api.updateUserInfo({ ...this.profile(), enforceMonthlyLimit: false }); auth.save({ ...auth.user(), ...login, ...this.profile(), nickname: this.form.username.trim(), needsProfileSetup: false }); this.success() } catch (error) { uni.showToast({ title: error.message || '手机号绑定失败，请重新授权', icon: 'none' }) } finally { this.saving = false } }, async submit() { if (!this.ready || this.saving) return; this.saving = true; try { await api.updateUserInfo({ ...this.profile(), enforceMonthlyLimit: false }); auth.save({ ...auth.user(), ...this.profile(), nickname: this.form.username.trim(), needsProfileSetup: false }); this.success() } catch (error) { uni.showToast({ title: error.message || '资料保存失败，请重试', icon: 'none' }) } finally { this.saving = false } }, success() { uni.showToast({ title: '注册成功', icon: 'success' }); setTimeout(() => uni.reLaunch({ url: '/pages/index/index' }), 1200) } } }
</script>

<style>
.auth-page{display:grid;min-height:100vh;place-items:center;overflow:hidden;background:#eef2f6;color:#17212d;font-family:"SF Pro Display","PingFang SC",sans-serif}.auth-shell{position:relative;width:min(1000px,calc(100vw - 48px));height:min(620px,calc(100vh - 90px));min-height:545px;overflow:hidden;border:1px solid #e2e8ef;border-radius:22px;background:#f8fafc;box-shadow:18px 18px 32px #cfd6df,-15px -15px 28px #fff}.auth-form-side,.auth-switch-side{position:absolute;top:0;bottom:0;width:50%;transition:transform .7s cubic-bezier(.77,0,.18,1)}.auth-form-side{left:0;z-index:2;background:#f8fafc}.auth-switch-side{right:0;display:grid;place-items:center;overflow:hidden;background:#edf1f5}.auth-shell.is-register .auth-form-side{transform:translateX(100%)}.auth-shell.is-register .auth-switch-side{transform:translateX(-100%)}.auth-back{position:absolute;top:28px;left:32px;color:#8793a1;font-size:12px;text-decoration:none}.auth-content{box-sizing:border-box;width:min(75%,350px);margin:0 auto;padding-top:74px}.auth-mark{display:flex;align-items:center;gap:8px;color:#17212d;font-size:12px;font-weight:800;letter-spacing:.16em}.auth-mark image{width:25px;height:25px}.auth-title{display:block;margin-top:32px;font-size:32px;font-weight:760;letter-spacing:-.06em}.auth-subtitle{display:block;margin-top:11px;color:#8a96a4;font-size:13px;line-height:1.65}.auth-methods{display:flex;gap:10px;margin:25px 0 20px}.auth-method{display:grid;width:31px;height:31px;place-items:center;border:1px solid #d3dbe5;border-radius:50%;color:#98a4b2;font-size:9px}.auth-method.active{border-color:#0a6edb;background:#e7f2ff;color:#0a6edb}.auth-fields{display:grid;gap:12px}.auth-fields label>text{display:block;margin-bottom:6px;color:#3d4b5a;font-size:12px;font-weight:650}.auth-fields input{box-sizing:border-box;width:100%;height:43px;padding:0 13px;border:1px solid #dce3eb;border-radius:8px;background:#fbfcfd;color:#17212d;font:inherit;font-size:13px;outline:0;transition:border-color .2s,box-shadow .2s}.auth-fields input:focus{border-color:#0a6edb;box-shadow:0 0 0 3px rgba(10,110,219,.11)}.auth-placeholder{color:#b5bec9}.auth-options{display:flex;align-items:center;justify-content:space-between;margin:16px 0 22px;color:#8b96a3;font-size:11px}.auth-options label{display:flex;align-items:center}.auth-options checkbox{margin-left:-5px;transform:scale(.75)}.auth-options>text{color:#0a6edb;cursor:pointer}.auth-submit,.switch-content button{height:45px;border:0;border-radius:999px;background:#0a6edb;color:#fff;font-size:12px;font-weight:800;letter-spacing:.12em;box-shadow:0 8px 17px rgba(10,110,219,.24);transition:transform .2s,background .2s}.auth-submit{width:100%}.auth-submit:after,.switch-content button:after{border:0}.auth-submit:hover,.switch-content button:hover{background:#087de9;transform:translateY(-2px)}.auth-note{display:block;margin-top:13px;color:#a2acb7;font-size:10px;line-height:1.45}.switch-content{position:relative;z-index:1;width:70%;text-align:center}.switch-content>text{display:block}.switch-content>text:first-child{font-size:34px;font-weight:760;letter-spacing:-.055em}.switch-content>text:nth-child(2){max-width:285px;margin:16px auto 31px;color:#8b96a3;font-size:13px;line-height:1.7}.switch-content button{width:165px}.corner-disc{position:absolute;width:250px;height:250px;border:1px solid #dde5ed;border-radius:50%;box-shadow:inset 11px 11px 23px rgba(187,198,210,.25),inset -10px -10px 20px rgba(255,255,255,.95)}.corner-disc-top{top:-160px;left:-80px}.corner-disc-bottom{right:-120px;bottom:-155px;width:325px;height:325px}@media(max-width:720px){.auth-page{display:block;padding:22px 0}.auth-shell{width:calc(100vw - 32px);height:auto;min-height:650px;margin:auto}.auth-form-side,.auth-switch-side{position:relative;width:100%;min-height:0;transform:none!important}.auth-form-side{padding-bottom:36px}.auth-switch-side{height:225px}.auth-shell.is-register .auth-switch-side{display:none}.auth-shell.is-register .auth-form-side{transform:none}.auth-content{width:calc(100% - 56px);padding-top:68px}.auth-title{font-size:29px}.auth-back{top:24px;left:28px}.switch-content>text:first-child{font-size:28px}.corner-disc-bottom{width:210px;height:210px;right:-95px;bottom:-100px}}
.auth-shell{width:min(1220px,calc(100vw - 72px));height:min(720px,calc(100vh - 64px));min-height:620px}.auth-submit,.switch-content button{display:flex!important;align-items:center;justify-content:center;box-sizing:border-box;padding:0!important;line-height:1!important;text-align:center}.auth-password>view{position:relative}.auth-password input{padding-right:92px!important}.auth-forgot{position:absolute;top:50%;right:13px;margin:0!important;color:#0a6edb!important;font-size:11px!important;font-weight:600!important;line-height:1!important;cursor:pointer;transform:translateY(-50%)}.auth-options{justify-content:flex-start}.auth-other{margin-top:20px;text-align:center}.auth-other>text{display:block;color:#9aa5b2;font-size:11px}.auth-other .auth-methods{justify-content:center;margin:11px 0 0}.auth-method{box-sizing:border-box;padding:0;background:transparent;line-height:29px}.auth-method:after{border:0}@media(max-width:720px){.auth-shell{width:calc(100vw - 32px);height:auto;min-height:650px}}
.page{min-height:100vh;display:flex;flex-direction:column;background:#fff}.header{padding:65px 24px 30px}.header .ui-strong,.header text{display:block}.header .ui-strong{font-size:28px;letter-spacing:1px}.header text{margin-top:8px;color:#636366;font-size:14px}.form{flex:1;padding:0 24px}.field{display:flex;align-items:center;justify-content:space-between;min-height:67px;border-bottom:1px solid #eee}.field>text{width:70px;font-size:15px;font-weight:500}.field input,.field picker{flex:1;text-align:right;font-size:15px}.field picker{padding:23px 0}.placeholder{color:#c7c7cc}.value{color:#0B0D10}.genders{display:flex;gap:10px}.genders view{width:58px;padding:8px 0;border:1px solid #e5e5ea;border-radius:6px;color:#636366;text-align:center;font-size:14px}.genders view.active{border-color:#0B0D10;background:#0B0D10;color:#fff}.bottom{padding:30px 24px calc(20px + env(safe-area-inset-bottom))}.bottom button{border-radius:9px;background:#0B0D10;color:#fff;font-size:16px;line-height:46px}.bottom button::after{border:0}.bottom button.disabled{opacity:.35;pointer-events:none}
</style>
